rows=[json.loads(l) for l in open('digest_check/runs/jev.jsonl')]
print("FLAGGED")
for r in sorted(rows,key=lambda r:-r['contradiction']):
    if r['contradiction']>=0.5 and r['coverage']>=0.5:
        t = pl[r['claim_id']]['altered_text'] if r['plant'] else c[r['claim_id']]['text']
        print(r['pair'], r['section_id'], r['contradiction'], r['coverage'], '|', t[:100])
print("PLANTS")
for r in rows:
    if r['plant']: print(r['pair'], r['contradiction'], r['coverage'])
print("NEAR (contr>=0.3)")
for r in rows:
    if 0.3<=r['contradiction'] and not (r['contradiction']>=0.5 and r['coverage']>=0.5): print(r['pair'], r['contradiction'], r['coverage'])
print("NUMBERS"); print(open('digest_check/runs/numbers.jsonl').read())
EOF

